package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class SlaEscalationsAcceptance {
 static final long START=SlaAlertsAcceptance.START;
 static String api(String clock){return "/api/openservice/clocks/"+clock+"/escalation";}
 static Map<String,Object> step(int percent,String recipient){return map("percent",percent,"recipient",recipient);}
 static Map<String,Object> plan(Object... steps){return map("steps",Arrays.asList(steps));}
 static String start(WorkflowSupport h,String record)throws Exception{String calendar="Warnings"+id();PlatformOperationsAcceptance.post(h,"calendars",map("name",calendar,"calendar",PlatformFoundationTest.calendar()));return PlatformOperationsAcceptance.post(h,"clocks",map("table","incident","record_id",record,"calendar",calendar,"minutes",4)).get("sla_id").toString();}
 static void reset(Store store,String clock,long time)throws Exception{try(var db=store.open()){db.update("UPDATE os_sla SET last_tick=?,remaining_ms=240000 WHERE sla_id=?",time,clock);db.connection.commit();}}
 static Map<String,Object> configure(WorkflowSupport h,String clock,Object plan)throws Exception{return result(h.json("POST",api(clock),plan,auth("admin")));}
 static List<Map<String,Object>> receipts(WorkflowSupport h,String clock)throws Exception{return objects(get(h,api(clock),"admin").get("receipts"));}
 static String clock(WorkflowSupport h,String record,Object plan)throws Exception{String id=start(h,record);configure(h,id,plan);reset(h.store,id,START);return id;}
 static void control(Store store,String clock,String action,long time)throws Exception{try(var db=store.open()){String actor=PlatformFoundationTest.bind(db);ServiceClocks.control(db,actor,clock,action,time);db.connection.commit();}}
 static void run(WorkflowSupport h)throws Exception {
  h.account("WarningAssignee","agent");h.account("WarningManager","agent");h.account("WarningFormer","agent");String record=h.add("incident").get("sys_id").toString(),group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);group=Service.create(db,"sys_user_group",map("short_description","Warning team","manager","WarningFormer"),"admin").get("sys_id").toString();db.connection.commit();}SlaAlertsAcceptance.assign(h,record,"WarningFormer",group);
  String clock=clock(h,record,plan(step(90,"responsible"),step(50,"assignee"),step(75,"group_manager")));assertEquals(50,objects(get(h,api(clock),"admin").get("steps")).getFirst().get("percent"));SlaAlertsAcceptance.assign(h,record,"WarningAssignee",group);result(h.json("PATCH","/api/now/table/sys_user_group/"+group,map("manager","WarningManager"),auth("admin")));SlaAlertsAcceptance.tick(h.store,START+119999);assertTrue(receipts(h,clock).isEmpty());SlaAlertsAcceptance.tick(h.store,START+120000);assertEquals(1,receipts(h,clock).size());assertEquals(1,SlaAlertsAcceptance.notices(h,"WarningAssignee").size());assertTrue(SlaAlertsAcceptance.notices(h,"WarningFormer").isEmpty());assertTrue(SlaAlertsAcceptance.notices(h,"WarningManager").isEmpty());
  String notice=SlaAlertsAcceptance.notices(h,"WarningAssignee").getFirst().get("notice_id").toString();assertEquals("/record/incident/"+record+"/clocks",get(h,SlaAlertsAcceptance.context(notice),"WarningAssignee").get("url"));assertEquals(404,h.get(SlaAlertsAcceptance.context(notice),auth("WarningManager")).statusCode());SlaAlertsAcceptance.tick(h.store,START+180000);assertEquals(1,SlaAlertsAcceptance.notices(h,"WarningManager").size());new Store(h.environment);SlaAlertsAcceptance.tick(h.store,START+216000);assertEquals(3,receipts(h,clock).size());assertEquals(2,SlaAlertsAcceptance.notices(h,"WarningAssignee").size());assertEquals(2,SlaAlertsAcceptance.notices(h,"WarningManager").size());SlaAlertsAcceptance.tick(h.store,START+216001);assertEquals(3,receipts(h,clock).size());SlaAlertsAcceptance.tick(h.store,START+240000);assertEquals(3,SlaAlertsAcceptance.notices(h,"WarningAssignee").size());assertEquals(3,SlaAlertsAcceptance.notices(h,"WarningManager").size());assertEquals(2,SlaAlertsAcceptance.notices(h,"admin").size());
  ProblemInvestigationsAcceptance.access(h,"incident",record,"private",FieldDispatchAcceptance.uid(h,"admin"));assertEquals(404,h.get(SlaAlertsAcceptance.context(notice),auth("WarningAssignee")).statusCode());
 }
 static void calendars(WorkflowSupport h)throws Exception {
  String record=h.add("incident").get("sys_id").toString();String clock=clock(h,record,plan(step(25,"owner"),step(50,"owner"),step(99,"owner")));long friday=PlatformFoundationTest.at("2026-11-20T16:59:00Z"),monday=PlatformFoundationTest.at("2026-11-23T09:00:00Z");reset(h.store,clock,friday);SlaAlertsAcceptance.tick(h.store,friday+59999);assertTrue(receipts(h,clock).isEmpty());SlaAlertsAcceptance.tick(h.store,monday);assertEquals(1,receipts(h,clock).size());control(h.store,clock,"pause",monday);SlaAlertsAcceptance.tick(h.store,monday+3600000);assertEquals(1,receipts(h,clock).size());control(h.store,clock,"resume",monday+3600000);SlaAlertsAcceptance.tick(h.store,monday+3659999);assertEquals(1,receipts(h,clock).size());SlaAlertsAcceptance.tick(h.store,monday+3660000);assertEquals(2,receipts(h,clock).size());control(h.store,clock,"complete",monday+3660000);SlaAlertsAcceptance.tick(h.store,monday+7200000);assertEquals(2,receipts(h,clock).size());
  String jump=clock(h,record,plan(step(1,"owner"),step(50,"owner"),step(99,"owner")));SlaAlertsAcceptance.tick(h.store,START+240000);assertEquals(List.of(1,50,99),receipts(h,jump).stream().map(x->(Integer)x.get("percent")).toList());for(var receipt:receipts(h,jump)){var detail=object(receipt.get("detail"));assertEquals(240000,((Number)detail.get("consumed_ms")).longValue());assertEquals(240000,((Number)detail.get("budget_ms")).longValue());}
  String paused=start(h,record);control(h.store,paused,"pause",System.currentTimeMillis());configure(h,paused,plan(step(99,"owner")));assertEquals(true,get(h,api(paused),"admin").get("configured"));
 }
 static void boundaries(WorkflowSupport h)throws Exception {
  h.account("WarningReader","reader");h.account("WarningStaff","agent");String record=h.add("incident").get("sys_id").toString(),clock=start(h,record);assertEquals(401,h.get(api(clock),null).statusCode());for(String user:List.of("WarningReader","WarningStaff")){assertEquals(403,h.get(api(clock),auth(user)).statusCode());assertEquals(403,h.json("POST",api(clock),plan(step(50,"owner")),auth(user)).statusCode());}assertEquals(404,h.get(api(id()),auth("admin")).statusCode());assertEquals(405,h.json("DELETE",api(clock),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(clock)+"?extra=1",auth("admin")).statusCode());
  for(Object input:List.of(map("extra",1),map("steps","bad"),plan(),plan(step(1,"owner"),step(2,"owner"),step(3,"owner"),step(4,"owner")),plan("bad"),plan(map("percent",50)),plan(map("percent","50","recipient","owner")),plan(step(0,"owner")),plan(step(100,"owner")),plan(step(50,"unknown")),plan(step(50,"")),plan(step(50,"owner"),step(50,"assignee"))))assertEquals(400,h.json("POST",api(clock),input,auth("admin")).statusCode(),input.toString());
  String html="/record/incident/"+record+"/clocks/"+clock+"/escalation";assertEquals(404,h.get(html.replace("/incident/","/problem/"),auth("admin")).statusCode());assertEquals(404,h.get(html.replace(record,id()),auth("admin")).statusCode());assertEquals(400,h.protectedForm(html,map("extra","bad"),auth("admin")).statusCode());var form=map("percent1","","recipient1","owner","percent2","","recipient2","","percent3","","recipient3","");assertEquals(400,h.protectedForm(html,form,auth("admin")).statusCode());
  String legacy=start(h,record);try(var db=h.store.open()){db.update("DELETE FROM os_sla_budget WHERE sla_id=?",legacy);db.connection.commit();}assertEquals(0,object(get(h,api(legacy),"admin").get("clock")).get("budget_ms"));assertEquals(400,h.json("POST",api(legacy),plan(step(50,"owner")),auth("admin")).statusCode());assertTrue(html(h.get("/record/incident/"+record+"/clocks/"+legacy+"/escalation",auth("admin"))).contains("original budget of this earlier clock is unknown"));
  for(String terminal:List.of("complete","cancel")){String ended=start(h,record);control(h.store,ended,terminal,System.currentTimeMillis());assertEquals(400,h.json("POST",api(ended),plan(step(50,"owner")),auth("admin")).statusCode());}
  String late=start(h,record);try(var db=h.store.open()){db.update("UPDATE os_sla SET remaining_ms=120000 WHERE sla_id=?",late);db.connection.commit();}assertEquals(400,h.json("POST",api(late),plan(step(50,"owner")),auth("admin")).statusCode());configure(h,clock,plan(step(50,"owner")));assertEquals(409,h.json("POST",api(clock),plan(step(75,"owner")),auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception {
  h.account("WarningEligibility","agent");String record=h.add("incident").get("sys_id").toString(),uid=FieldDispatchAcceptance.uid(h,"WarningEligibility");SlaAlertsAcceptance.assign(h,record,"WarningEligibility","");
  for(String setting:List.of("notifications=0","active=0","role='reader'","password_reset_required=1")){String clock=clock(h,record,plan(step(50,"assignee")));try(var db=h.store.open()){db.update("UPDATE os_user SET notifications=1,active=1,role='agent',password_reset_required=0 WHERE user_id=?",uid);db.update("UPDATE os_user SET "+setting+" WHERE user_id=?",uid);db.connection.commit();}SlaAlertsAcceptance.tick(h.store,START+120000);var outcomes=objects(object(receipts(h,clock).getFirst().get("detail")).get("outcomes"));assertEquals(setting.startsWith("notifications")?"disabled":"unavailable",outcomes.getFirst().get("outcome"));try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_notice WHERE user_id=?",uid));db.update("UPDATE os_user SET notifications=1,active=1,role='agent',password_reset_required=0 WHERE user_id=?",uid);db.connection.commit();}SlaAlertsAcceptance.tick(h.store,START+120001);assertTrue(SlaAlertsAcceptance.notices(h,"WarningEligibility").isEmpty());}
  String hidden=clock(h,record,plan(step(50,"assignee")));ProblemInvestigationsAcceptance.access(h,"incident",record,"private",FieldDispatchAcceptance.uid(h,"admin"));SlaAlertsAcceptance.tick(h.store,START+120000);assertEquals("unavailable",objects(object(receipts(h,hidden).getFirst().get("detail")).get("outcomes")).getFirst().get("outcome"));ProblemInvestigationsAcceptance.access(h,"incident",record,"workspace","");
  Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"incident");}String denied=clock(h,record,plan(step(50,"responsible")));var changed=new LinkedHashMap<>(schema);changed.put("record_roles",map("read",List.of("reader")));ReferencePickerAcceptance.writeSchema(h,"incident",changed);try{assertEquals(403,h.get(api(denied),auth("admin")).statusCode());assertEquals(403,h.json("POST",api(startWithoutRead(h,record)),plan(step(50,"owner")),auth("admin")).statusCode());SlaAlertsAcceptance.tick(h.store,START+120000);}finally{ReferencePickerAcceptance.writeSchema(h,"incident",schema);}for(var outcome:objects(object(receipts(h,denied).getFirst().get("detail")).get("outcomes")))assertEquals("unavailable",outcome.get("outcome"));
  SlaAlertsAcceptance.assign(h,record,"admin","");String same=clock(h,record,plan(step(50,"responsible")));SlaAlertsAcceptance.tick(h.store,START+120000);assertEquals(1,objects(object(receipts(h,same).getFirst().get("detail")).get("outcomes")).size());SlaAlertsAcceptance.assign(h,record,"MissingAccount","");String empty=clock(h,record,plan(step(50,"assignee"),step(75,"group_manager")));SlaAlertsAcceptance.tick(h.store,START+180000);for(var receipt:receipts(h,empty))assertTrue(objects(object(receipt.get("detail")).get("outcomes")).isEmpty());
  String removed=clock(h,record,plan(step(50,"owner")));try(var db=h.store.open()){db.update("DELETE FROM os_record WHERE sys_id=?",record);db.connection.commit();}SlaAlertsAcceptance.tick(h.store,START+120000);try(var db=h.store.open()){assertEquals(false,object(db.one("SELECT detail FROM os_sla_threshold WHERE sla_id=?",removed).get("detail")).get("record_available"));}assertEquals(404,h.get(api(removed),auth("admin")).statusCode());
 }
 static String startWithoutRead(WorkflowSupport h,String record)throws Exception{try(var db=h.store.open()){return db.one("SELECT sla_id FROM os_sla WHERE record_id=? ORDER BY sla_id",record).get("sla_id").toString();}}
 static void concurrency(WorkflowSupport h)throws Exception {
  String record=h.add("incident").get("sys_id").toString(),clock=start(h,record);var plan=plan(step(50,"owner"));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var signal=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{signal.await();return h.json("POST",api(clock),plan,auth("admin")).statusCode();});var b=pool.submit(()->{signal.await();return h.json("POST",api(clock),plan,auth("admin")).statusCode();});signal.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}reset(h.store,clock,START);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->{SlaAlertsAcceptance.tick(h.store,START+120000);return true;});var b=pool.submit(()->{SlaAlertsAcceptance.tick(h.store,START+120000);return true;});assertTrue(a.get());assertTrue(b.get());}new Store(h.environment);SlaAlertsAcceptance.tick(h.store,START+120001);assertEquals(1,receipts(h,clock).size());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_notice_target WHERE target_id=?",clock));}
 }
}
